<template><component :is="config.layout.layoutMode" /></template>
<script setup lang="ts">
import {useEventListener} from '@vueuse/core';import {onBeforeMount,onMounted,reactive} from 'vue';import Classic from '/@/layouts/backend/container/classic.vue';import Default from '/@/layouts/backend/container/default.vue';import Double from '/@/layouts/backend/container/double.vue';import Streamline from '/@/layouts/backend/container/streamline.vue';import LeftSplit from '/@/layouts/backend/container/leftSplit.vue';import {useConfig} from '/@/stores/config';import {useAdminInfo} from '/@/stores/adminInfo';import {BEFORE_RESIZE_LAYOUT} from '/@/stores/constant/cacheKey';import {Session} from '/@/utils/storage';import {setNavTabsWidth} from '/@/utils/layout';
defineOptions({components:{Default,Classic,Streamline,Double,LeftSplit}});const config=useConfig(),adminInfo=useAdminInfo();const state=reactive({autoMenuCollapseLock:false});onMounted(()=>{adminInfo.dataFill({id:1,username:'lms-admin',nickname:'LMS Admin',super:true});setNavTabsWidth();useEventListener(window,'resize',setNavTabsWidth)});onBeforeMount(()=>{onAdaptiveLayout();useEventListener(window,'resize',onAdaptiveLayout)});function onAdaptiveLayout(){const defaults={menuCollapse:config.layout.menuCollapse};let before=Session.get(BEFORE_RESIZE_LAYOUT);if(!before)Session.set(BEFORE_RESIZE_LAYOUT,defaults);if(document.body.clientWidth<1024){if(!state.autoMenuCollapseLock){state.autoMenuCollapseLock=true;config.setLayout('menuCollapse',true)}config.setLayout('shrink',true)}else{state.autoMenuCollapseLock=false;config.setLayout('menuCollapse',(before||defaults).menuCollapse);config.setLayout('shrink',false)}}
</script>
